-- Apply to Supabase. No production users or patient seed data are created.
begin;
create table public.profiles (id uuid primary key references auth.users(id), full_name text not null default '', created_at timestamptz not null default now());
create table public.platform_admins (user_id uuid primary key references auth.users(id), created_at timestamptz not null default now());
create table public.pharmacies (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 180), city text not null, phone text, owner_email text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.pharmacy_memberships (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, user_id uuid not null references auth.users, role text not null check(role in ('owner','pharmacist','technician')), active boolean not null default true, created_at timestamptz not null default now(), unique(pharmacy_id,user_id));
create table public.subscription_plans (id uuid primary key default gen_random_uuid(), name text not null unique, price numeric(14,2) not null check(price>=0), currency text not null default 'IQD' check(length(currency)=3), staff_limit integer not null check(staff_limit>0), patient_limit integer not null check(patient_limit>0), ai_limit integer not null default 0 check(ai_limit>=0), active boolean not null default true, created_at timestamptz not null default now());
create table public.subscriptions (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null unique references public.pharmacies, plan_id uuid not null references public.subscription_plans, status text not null check(status in ('trial','active','past_due','grace_period','suspended','expired','canceled')), starts_on date not null, ends_on date not null, staff_limit integer not null check(staff_limit>0), patient_limit integer not null check(patient_limit>0), ai_limit integer not null default 0 check(ai_limit>=0), created_at timestamptz not null default now(), check(ends_on>=starts_on));
create table public.subscription_invoices (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, invoice_number text not null unique, amount numeric(14,2) not null check(amount>0), currency text not null default 'IQD' check(length(currency)=3), due_on date not null, status text not null default 'pending' check(status in ('pending','paid','overdue','void')), created_at timestamptz not null default now(), unique(pharmacy_id,id));
create table public.subscription_payments (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, invoice_id uuid not null, amount numeric(14,2) not null check(amount>0), currency text not null default 'IQD' check(length(currency)=3), paid_on date not null, method text not null check(method in ('cash','bank_transfer','local_wallet','other')), reference text, notes text, confirmed_by uuid references auth.users, confirmed_at timestamptz, created_at timestamptz not null default now(), foreign key(pharmacy_id,invoice_id) references public.subscription_invoices(pharmacy_id,id), check((confirmed_by is null)=(confirmed_at is null)));
create table public.platform_settings (id uuid primary key default gen_random_uuid(), key text not null unique, value text not null, created_at timestamptz not null default now());
create table public.feature_entitlements (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, feature text not null, enabled boolean not null default false, unique(pharmacy_id,feature));
create table public.pharmacy_invitations (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, email text not null, role text not null check(role in ('owner','pharmacist','technician')), status text not null default 'pending' check(status in ('pending','sent','accepted','revoked','failed')), expires_at timestamptz not null default now()+interval '48 hours', invited_by uuid not null references auth.users, provider_user_id uuid references auth.users, created_at timestamptz not null default now());
create unique index invitation_pending_email on public.pharmacy_invitations(pharmacy_id,lower(email)) where status in ('pending','sent','failed');
create table public.administrative_audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users, action text not null, record_id uuid, created_at timestamptz not null default now());
create table public.patients (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, display_number bigint generated always as identity, full_name text not null check(length(full_name) between 2 and 160), phone text not null check(phone ~ '^\+9647[0-9]{9}$'), city text not null default '', date_of_birth date, estimated_age integer check(estimated_age between 0 and 130), age_reference_on date, gender text check(gender in ('female','male','other','unspecified')), conditions text not null default '', notes text not null default '', communication_consent boolean not null default false, status text not null default 'active' check(status in ('active','inactive','archived')), created_by uuid not null default auth.uid() references auth.users, updated_by uuid not null default auth.uid() references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(pharmacy_id,id), unique(pharmacy_id,display_number), check(estimated_age is null or age_reference_on is not null));
create index patients_search_name on public.patients(pharmacy_id,lower(full_name));
create index patients_search_phone on public.patients(pharmacy_id,phone);
create table public.patient_conditions (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, patient_id uuid not null, name text not null, created_at timestamptz not null default now(), foreign key(pharmacy_id,patient_id) references public.patients(pharmacy_id,id));
create table public.medication_catalog (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, name text not null, strength text, form text, created_at timestamptz not null default now());
create table public.patient_medications (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, patient_id uuid not null, medicine_name text not null check(length(medicine_name) between 1 and 200), strength text not null, form text not null, route text not null, instructions text not null, status text not null default 'draft' check(status in ('draft','active','paused','discontinued')), created_by uuid not null default auth.uid() references auth.users, updated_by uuid not null default auth.uid() references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(pharmacy_id,id), unique(pharmacy_id,patient_id,id), foreign key(pharmacy_id,patient_id) references public.patients(pharmacy_id,id));
create table public.medication_regimens (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, medication_id uuid not null, instructions text not null, units_per_dose numeric check(units_per_dose>0), frequency text not null, effective_on date not null, created_by uuid not null default auth.uid() references auth.users, created_at timestamptz not null default now(), foreign key(pharmacy_id,medication_id) references public.patient_medications(pharmacy_id,id));
create table public.dispensing_events (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, patient_id uuid not null, medication_id uuid not null, request_id uuid not null default gen_random_uuid(), dispensed_on date not null, quantity numeric not null check(quantity>0 and quantity<=100000), days_supply integer not null check(days_supply between 1 and 730), lead_days integer not null default 2 check(lead_days between 0 and 60), carry_days integer not null default 0 check(carry_days between 0 and 730), carry_reviewed boolean not null default false, calculation_method text not null default 'pharmacist_confirmed' check(calculation_method in ('pharmacist_confirmed','estimated_floor')), last_covered_on date generated always as (dispensed_on+days_supply+carry_days-1) stored, contact_on date generated always as (dispensed_on+days_supply+carry_days-1-lead_days) stored, correction_of uuid, correction_reason text, created_by uuid not null default auth.uid() references auth.users, created_at timestamptz not null default now(), unique(pharmacy_id,id), unique(pharmacy_id,request_id), unique(pharmacy_id,patient_id,medication_id,id), foreign key(pharmacy_id,patient_id,medication_id) references public.patient_medications(pharmacy_id,patient_id,id), foreign key(pharmacy_id,correction_of) references public.dispensing_events(pharmacy_id,id), check(carry_days=0 or carry_reviewed), check(correction_of is null or coalesce(length(trim(correction_reason)),0)>=5));
create table public.refill_projections (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, patient_id uuid not null, medication_id uuid not null, dispensing_event_id uuid not null, last_covered_on date not null, contact_on date not null, updated_at timestamptz not null default now(), unique(pharmacy_id,medication_id), foreign key(pharmacy_id,patient_id,medication_id,dispensing_event_id) references public.dispensing_events(pharmacy_id,patient_id,medication_id,id));
create table public.refill_tasks (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, patient_id uuid not null, medication_id uuid not null, dispensing_event_id uuid not null, scheduled_on date not null, status text not null default 'pending' check(status in ('pending','completed','canceled')), assigned_to uuid references auth.users, completed_at timestamptz, created_at timestamptz not null default now(), unique(pharmacy_id,dispensing_event_id), foreign key(pharmacy_id,patient_id,medication_id,dispensing_event_id) references public.dispensing_events(pharmacy_id,patient_id,medication_id,id));
create table public.patient_contact_events (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, patient_id uuid not null, medication_id uuid, outcome text not null check(outcome in ('contacted','no_answer','will_return','declined','rescheduled')), contacted_on date not null default (now() at time zone 'Asia/Baghdad')::date, next_contact_on date, notes text, created_by uuid not null default auth.uid() references auth.users, created_at timestamptz not null default now(), foreign key(pharmacy_id,patient_id) references public.patients(pharmacy_id,id), foreign key(pharmacy_id,patient_id,medication_id) references public.patient_medications(pharmacy_id,patient_id,id));
create table public.laboratory_results (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, patient_id uuid not null, test_name text not null, result text not null, unit text, reference_range text, collected_on date not null, notes text, created_by uuid not null default auth.uid() references auth.users, updated_by uuid not null default auth.uid() references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(pharmacy_id,patient_id) references public.patients(pharmacy_id,id));
create table public.patient_documents (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, patient_id uuid not null, object_path text not null unique, mime_type text not null check(mime_type in ('image/jpeg','image/png','application/pdf')), size_bytes integer not null check(size_bytes between 1 and 5242880), category text not null check(category in ('prescription','laboratory','other')), archived_at timestamptz, created_by uuid not null default auth.uid() references auth.users, created_at timestamptz not null default now(), foreign key(pharmacy_id,patient_id) references public.patients(pharmacy_id,id), check(split_part(object_path,'/',1)=pharmacy_id::text));
create table public.clinical_audit_logs (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, actor_id uuid references auth.users, action text not null, record_id uuid not null, created_at timestamptz not null default now());
create table public.ai_extraction_jobs (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, requested_by uuid not null default auth.uid() references auth.users, status text not null check(status in ('pending','completed','failed','reviewed')), model text not null, created_at timestamptz not null default now());
create table public.ai_usage_records (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, job_id uuid not null unique references public.ai_extraction_jobs, input_tokens integer not null default 0 check(input_tokens>=0), output_tokens integer not null default 0 check(output_tokens>=0), estimated_cost numeric(12,6) check(estimated_cost>=0), created_at timestamptz not null default now());
create table public.notification_preferences (id uuid primary key default gen_random_uuid(), pharmacy_id uuid not null references public.pharmacies, user_id uuid not null default auth.uid() references auth.users, lead_days integer not null default 2 check(lead_days between 0 and 60), unique(pharmacy_id,user_id));
create table public.scheduled_job_runs (id uuid primary key default gen_random_uuid(), job_name text not null, status text not null check(status in ('running','completed','failed')), started_at timestamptz not null default now(), completed_at timestamptz);
create table public.application_events (id uuid primary key default gen_random_uuid(), pharmacy_id uuid references public.pharmacies, event_type text not null, created_at timestamptz not null default now());

create function public.is_platform_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.platform_admins where user_id=auth.uid()) $$;
create function public.member_role(p_id uuid) returns text language sql stable security definer set search_path='' as $$ select role from public.pharmacy_memberships where pharmacy_id=p_id and user_id=auth.uid() and active $$;
create function public.can_read(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.member_role(p_id) is not null and exists(select 1 from public.subscriptions s where s.pharmacy_id=p_id and (now() at time zone 'Asia/Baghdad')::date <= s.ends_on+90) $$;
create function public.can_write(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.member_role(p_id) is not null and exists(select 1 from public.subscriptions s where s.pharmacy_id=p_id and s.status in ('trial','active','grace_period') and (now() at time zone 'Asia/Baghdad')::date between s.starts_on and s.ends_on + case when s.status='grace_period' then 7 else 0 end) $$;

alter table public.profiles enable row level security;
create policy self_profile on public.profiles for select to authenticated using(id=auth.uid());
alter table public.platform_admins enable row level security;
create policy self_admin on public.platform_admins for select to authenticated using(user_id=auth.uid());
alter table public.pharmacies enable row level security;
create policy pharmacy_read on public.pharmacies for select to authenticated using(public.is_platform_admin() or public.member_role(id) is not null);
create policy pharmacy_admin on public.pharmacies for all to authenticated using(public.is_platform_admin()) with check(public.is_platform_admin());
alter table public.pharmacy_memberships enable row level security;
create policy membership_read on public.pharmacy_memberships for select to authenticated using(user_id=auth.uid() or public.member_role(pharmacy_id)='owner');
alter table public.pharmacy_invitations enable row level security;
create policy invitation_read on public.pharmacy_invitations for select to authenticated using(public.is_platform_admin() or public.member_role(pharmacy_id)='owner');

do $$ declare t text; begin
 foreach t in array array['subscription_plans','subscriptions','subscription_invoices','subscription_payments','platform_settings','feature_entitlements'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('create policy admin_manage on public.%I for all to authenticated using(public.is_platform_admin()) with check(public.is_platform_admin())',t);
 if t in ('subscriptions','subscription_invoices','subscription_payments','feature_entitlements') then execute format('create policy member_read on public.%I for select to authenticated using(public.member_role(pharmacy_id) is not null)',t); end if;
 end loop;
 foreach t in array array['administrative_audit_logs','scheduled_job_runs'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('create policy admin_read on public.%I for select to authenticated using(public.is_platform_admin())',t);
 end loop;
 foreach t in array array['patients','patient_conditions','medication_catalog','patient_medications','medication_regimens','dispensing_events','refill_projections','refill_tasks','patient_contact_events','laboratory_results','patient_documents','clinical_audit_logs','ai_extraction_jobs','ai_usage_records','notification_preferences','application_events'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('create index on public.%I (pharmacy_id)',t);
 execute format('create policy tenant_read on public.%I for select to authenticated using(public.can_read(pharmacy_id))',t);
 if t in ('patients','patient_contact_events','notification_preferences') then
 execute format('create policy tenant_insert on public.%I for insert to authenticated with check(public.can_write(pharmacy_id))',t);
 if t<>'patient_contact_events' then execute format('create policy tenant_update on public.%I for update to authenticated using(public.can_write(pharmacy_id)) with check(public.can_write(pharmacy_id))',t); end if;
 elsif t in ('patient_medications','patient_conditions','medication_catalog','medication_regimens','laboratory_results') then
 execute format('create policy clinical_insert on public.%I for insert to authenticated with check(public.can_write(pharmacy_id) and public.member_role(pharmacy_id) in (''owner'',''pharmacist''))',t);
 if t<>'medication_regimens' then execute format('create policy clinical_update on public.%I for update to authenticated using(public.can_write(pharmacy_id) and public.member_role(pharmacy_id) in (''owner'',''pharmacist'')) with check(public.can_write(pharmacy_id) and public.member_role(pharmacy_id) in (''owner'',''pharmacist''))',t); end if;
 end if;
 end loop;
end $$;

-- Identity and tenant context cannot be changed through payload edits.
create function public.protect_context() returns trigger language plpgsql set search_path='' as $$ begin
 if new.pharmacy_id is distinct from old.pharmacy_id or new.id is distinct from old.id then raise exception 'Immutable record context'; end if;
 if to_jsonb(new) ? 'patient_id' and to_jsonb(new)->>'patient_id' is distinct from to_jsonb(old)->>'patient_id' then raise exception 'Immutable patient context'; end if;
 if to_jsonb(new) ? 'created_by' then new.created_by=old.created_by; end if;
 if to_jsonb(new) ? 'created_at' then new.created_at=old.created_at; end if;
 if to_jsonb(new) ? 'updated_at' then new.updated_at=now(); end if;
 if to_jsonb(new) ? 'updated_by' then new.updated_by=auth.uid(); end if;
 return new; end $$;
do $$ declare t text; begin foreach t in array array['patients','patient_conditions','patient_medications','medication_catalog','laboratory_results','notification_preferences','subscriptions','subscription_invoices','subscription_payments','feature_entitlements'] loop execute format('create trigger protect_context before update on public.%I for each row execute function public.protect_context()',t); end loop; end $$;
create function public.audit_record() returns trigger language plpgsql security definer set search_path='' as $$ begin
 insert into public.clinical_audit_logs(pharmacy_id,actor_id,action,record_id) values(new.pharmacy_id,auth.uid(),lower(TG_OP)||':'||TG_TABLE_NAME,new.id); return new; end $$;
do $$ declare t text; begin foreach t in array array['patients','patient_conditions','patient_medications','medication_regimens','dispensing_events','patient_contact_events','laboratory_results','patient_documents'] loop execute format('create trigger audit_record after insert or update on public.%I for each row execute function public.audit_record()',t); end loop; end $$;
create function public.audit_admin() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.administrative_audit_logs(actor_id,action,record_id) values(auth.uid(),lower(TG_OP)||':'||TG_TABLE_NAME,new.id); return new; end $$;
do $$ declare t text; begin foreach t in array array['pharmacies','subscription_plans','subscriptions','subscription_invoices','subscription_payments','pharmacy_invitations','pharmacy_memberships','platform_settings'] loop execute format('create trigger audit_admin after insert or update on public.%I for each row execute function public.audit_admin()',t); end loop; end $$;
create function public.limit_patients() returns trigger language plpgsql security definer set search_path='' as $$ declare max_patients integer; begin
 perform 1 from public.pharmacies where id=new.pharmacy_id for update;
 select patient_limit into max_patients from public.subscriptions where pharmacy_id=new.pharmacy_id;
 if max_patients is null or (select count(*) from public.patients where pharmacy_id=new.pharmacy_id)>=max_patients then raise exception 'Patient limit reached'; end if;
 new.created_by=auth.uid();new.updated_by=auth.uid();return new; end $$;
create trigger limit_patients before insert on public.patients for each row execute function public.limit_patients();

create function public.record_dispensing(p_pharmacy uuid,p_input jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare e public.dispensing_events; m public.patient_medications; begin
 if not public.can_write(p_pharmacy) or public.member_role(p_pharmacy) not in ('owner','pharmacist') then raise exception 'Forbidden'; end if;
 select * into m from public.patient_medications where pharmacy_id=p_pharmacy and id=(p_input->>'medication_id')::uuid and patient_id=(p_input->>'patient_id')::uuid and status='active' for update;
 if not found then raise exception 'Active medication unavailable'; end if;
 if p_input->>'request_id' is not null then select * into e from public.dispensing_events where pharmacy_id=p_pharmacy and request_id=(p_input->>'request_id')::uuid; if found then if e.medication_id<>m.id or e.quantity<>(p_input->>'quantity')::numeric or e.days_supply<>(p_input->>'days_supply')::integer or e.dispensed_on<>(p_input->>'dispensed_on')::date then raise exception 'Idempotency key reused with different input'; end if; return e.id; end if; end if;
 if (p_input->>'dispensed_on')::date > (now() at time zone 'Asia/Baghdad')::date then raise exception 'Future dispensing not allowed'; end if;
 if p_input->>'correction_of' is not null and not exists(select 1 from public.dispensing_events where id=(p_input->>'correction_of')::uuid and pharmacy_id=p_pharmacy and medication_id=m.id) then raise exception 'Invalid correction target'; end if;
 insert into public.dispensing_events(pharmacy_id,patient_id,medication_id,request_id,dispensed_on,quantity,days_supply,lead_days,carry_days,carry_reviewed,correction_of,correction_reason)
 values(p_pharmacy,m.patient_id,m.id,coalesce((p_input->>'request_id')::uuid,gen_random_uuid()),(p_input->>'dispensed_on')::date,(p_input->>'quantity')::numeric,(p_input->>'days_supply')::integer,coalesce((p_input->>'lead_days')::integer,2),coalesce((p_input->>'carry_days')::integer,0),coalesce((p_input->>'carry_reviewed')::boolean,false),(p_input->>'correction_of')::uuid,p_input->>'correction_reason') returning * into e;
 -- Serialize on medication row. A late-entered historical event does not displace newer supply.
 if not exists(select 1 from public.refill_projections p join public.dispensing_events d on d.id=p.dispensing_event_id where p.pharmacy_id=p_pharmacy and p.medication_id=m.id and d.dispensed_on>e.dispensed_on) then
 insert into public.refill_projections(pharmacy_id,patient_id,medication_id,dispensing_event_id,last_covered_on,contact_on) values(p_pharmacy,m.patient_id,m.id,e.id,e.last_covered_on,e.contact_on)
 on conflict(pharmacy_id,medication_id) do update set dispensing_event_id=excluded.dispensing_event_id,last_covered_on=excluded.last_covered_on,contact_on=excluded.contact_on,updated_at=now();
 update public.refill_tasks set status='canceled' where pharmacy_id=p_pharmacy and medication_id=m.id and status='pending';
 insert into public.refill_tasks(pharmacy_id,patient_id,medication_id,dispensing_event_id,scheduled_on) values(p_pharmacy,m.patient_id,m.id,e.id,e.contact_on) on conflict(pharmacy_id,dispensing_event_id) do nothing;
 end if;
 return e.id; end $$;

-- Default grants never imply authorization: RLS above remains authoritative.
grant usage on schema public to authenticated;
grant select on all tables in schema public to authenticated;
grant insert,update on public.patients,public.patient_conditions,public.medication_catalog,public.patient_medications,public.medication_regimens,public.patient_contact_events,public.laboratory_results,public.notification_preferences,public.pharmacies,public.subscription_plans,public.subscriptions,public.subscription_invoices,public.platform_settings,public.feature_entitlements to authenticated;
grant insert on public.subscription_payments to authenticated;
grant usage,select on all sequences in schema public to authenticated;
revoke all on function public.record_dispensing(uuid,jsonb) from public;
grant execute on function public.record_dispensing(uuid,jsonb) to authenticated;
revoke all on function public.audit_record(),public.audit_admin(),public.limit_patients(),public.protect_context() from public;
commit;
